struct Json {
    enum Type { Null, Bool, Number, String, Array, Object } type = Null;
    std::string value;
    std::vector<Json> array;
    std::map<std::string, Json> object;
    const Json& get(const std::string& key) const { static Json empty; auto it=object.find(key); return it==object.end()?empty:it->second; }
    std::string str(const std::string& fallback="") const { return type==String||type==Number?value:fallback; }
    double number(double fallback=0) const { return type==Number?std::strtod(value.c_str(),nullptr):fallback; }
};
class Parser {
    const std::string& s; size_t i=0;
    void ws(){while(i<s.size()&&std::isspace((unsigned char)s[i]))++i;}
    std::string string(){ std::string o; ++i; while(i<s.size()){char c=s[i++]; if(c=='"')break; if(c=='\\'&&i<s.size()){char e=s[i++]; switch(e){case 'n':o+='\n';break;case 'r':o+='\r';break;case 't':o+='\t';break;default:o+=e;}}else o+=c;} return o; }
    Json value(){ws(); Json j; if(i>=s.size())return j; char c=s[i]; if(c=='"'){j.type=Json::String;j.value=string();} else if(c=='{'){j.type=Json::Object;++i;ws();while(i<s.size()&&s[i]!='}'){if(s[i]!=','){std::string k=string();ws();++i;j.object[k]=value();}else ++i;ws();}if(i<s.size())++i;} else if(c=='['){j.type=Json::Array;++i;ws();while(i<s.size()&&s[i]!=']'){if(s[i]!=',')j.array.push_back(value());else ++i;ws();}if(i<s.size())++i;}else if(s.compare(i,4,"true")==0){j.type=Json::Bool;j.value="true";i+=4;}else if(s.compare(i,5,"false")==0){j.type=Json::Bool;j.value="false";i+=5;}else if(s.compare(i,4,"null")==0)i+=4;else{j.type=Json::Number;size_t b=i;while(i<s.size()&&(std::isdigit((unsigned char)s[i])||s[i]=='-'||s[i]=='+'||s[i]=='.'||s[i]=='e'||s[i]=='E'))++i;j.value=s.substr(b,i-b);}return j;}
public: explicit Parser(const std::string& x):s(x){} Json parse(){return value();}
};
static std::string quote(const std::string& s){std::string o="\"";for(unsigned char c:s){switch(c){case '"':o+="\\\"";break;case '\\':o+="\\\\";break;case '\n':o+="\\n";break;case '\r':o+="\\r";break;case '\t':o+="\\t";break;default:if(c<32){char b[7];std::snprintf(b,sizeof b,"\\u%04x",c);o+=b;}else o+=c;}}return o+'"';}
static std::string raw(const Json& j){if(j.type==Json::Array){std::string o="[";for(size_t i=0;i<j.array.size();++i){if(i)o+=',';o+=raw(j.array[i]);}return o+"]";}if(j.type==Json::Null)return "null";if(j.type==Json::String)return quote(j.value);if(j.type==Json::Object)return "{}";return j.value;}
static std::string text(const Json& j){return j.type==Json::String?j.value:j.type==Json::Null?"":j.value;}
static void bindText(sqlite3_stmt* q,int n,const Json& j){std::string v=text(j);sqlite3_bind_text(q,n,v.c_str(),-1,SQLITE_TRANSIENT);}
static void bindNum(sqlite3_stmt* q,int n,const Json& j){if(j.type==Json::Number)sqlite3_bind_double(q,n,j.number());else sqlite3_bind_null(q,n);}
static std::string col(sqlite3_stmt* q,int n){const unsigned char* p=sqlite3_column_text(q,n);return p?(const char*)p:"";}
static std::string esc(const std::string& x){std::string o;for(char c:x){if(c=='"'||c=='\\')o+='\\';if(c=='\n')o+="\\n";else if(c=='\r')o+="\\r";else o+=c;}return o;}
static std::string recordJson(sqlite3_stmt* q){return "{\"id\":"+quote(col(q,0))+",\"systemId\":"+quote(col(q,1))+",\"systemName\":"+quote(col(q,2))+",\"evaluatorId\":"+quote(col(q,3))+",\"evaluatorName\":"+quote(col(q,4))+",\"userRole\":"+quote(col(q,5))+",\"beforeAnswers\":"+col(q,6)+",\"afterAnswers\":"+col(q,7)+",\"beforeAverage\":"+(sqlite3_column_type(q,8)==SQLITE_NULL?"null":std::to_string(sqlite3_column_double(q,8)))+",\"afterAverage\":"+(sqlite3_column_type(q,9)==SQLITE_NULL?"null":std::to_string(sqlite3_column_double(q,9)))+",\"comparableCount\":"+std::to_string(sqlite3_column_int(q,10))+",\"satisfactionAnswers\":"+col(q,11)+",\"satisfactionAverage\":"+(sqlite3_column_type(q,12)==SQLITE_NULL?"null":std::to_string(sqlite3_column_double(q,12)))+",\"feedback\":"+quote(col(q,13))+",\"submittedAt\":"+quote(col(q,14))+"}";}
static bool exec(sqlite3* db,const std::string& sql){char* e=nullptr;int rc=sqlite3_exec(db,sql.c_str(),nullptr,nullptr,&e);if(rc!=SQLITE_OK){std::cerr<<(e?e:sqlite3_errmsg(db))<<"\n";sqlite3_free(e);return false;}return true;}
static std::string hex(const unsigned char* data,size_t size){static const char* digits="0123456789abcdef";std::string out;out.reserve(size*2);for(size_t i=0;i<size;++i){out+=digits[data[i]>>4];out+=digits[data[i]&15];}return out;}
static bool passwordHash(const std::string& password,std::string& saltHex,std::string& hashHex){unsigned char salt[16],derived[32];if(BCryptGenRandom(nullptr,salt,sizeof salt,BCRYPT_USE_SYSTEM_PREFERRED_RNG)<0)return false;BCRYPT_ALG_HANDLE alg=nullptr;if(BCryptOpenAlgorithmProvider(&alg,BCRYPT_SHA256_ALGORITHM,nullptr,BCRYPT_ALG_HANDLE_HMAC_FLAG)<0)return false;NTSTATUS rc=BCryptDeriveKeyPBKDF2(alg,(PUCHAR)password.data(),(ULONG)password.size(),salt,sizeof salt,120000,derived,sizeof derived,0);BCryptCloseAlgorithmProvider(alg,0);if(rc<0)return false;saltHex=hex(salt,sizeof salt);hashHex=hex(derived,sizeof derived);return true;}
static std::string deriveWithSalt(const std::string& password,const std::string& saltHex){if(saltHex.size()!=32)return "";unsigned char salt[16],derived[32];for(size_t i=0;i<16;++i){auto digit=[](char c)->int{return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:c>='A'&&c<='F'?c-'A'+10:-1;};int a=digit(saltHex[i*2]),b=digit(saltHex[i*2+1]);if(a<0||b<0)return "";salt[i]=(unsigned char)((a<<4)|b);}BCRYPT_ALG_HANDLE alg=nullptr;if(BCryptOpenAlgorithmProvider(&alg,BCRYPT_SHA256_ALGORITHM,nullptr,BCRYPT_ALG_HANDLE_HMAC_FLAG)<0)return "";NTSTATUS rc=BCryptDeriveKeyPBKDF2(alg,(PUCHAR)password.data(),(ULONG)password.size(),salt,sizeof salt,120000,derived,sizeof derived,0);BCryptCloseAlgorithmProvider(alg,0);return rc<0?"":hex(derived,sizeof derived);}
static bool constantEqual(const std::string&a,const std::string&b){if(a.size()!=b.size())return false;unsigned char diff=0;for(size_t i=0;i<a.size();++i)diff|=(unsigned char)(a[i]^b[i]);return diff==0;}
static std::string auth(sqlite3*db,const std::string&path,const std::string&body,int&status){Json j=Parser(body).parse();std::string username=text(j.get("username")),password=text(j.get("password"));if(username.empty()||password.size()<8){status=400;return "{\"error\":\"username is required and password must be at least 8 characters\"}";}if(path=="/auth/register"){std::string display=text(j.get("displayName")),role=text(j.get("role"));if(display.empty())display=username;if(role!="student"&&role!="teacher"&&role!="staff")role="student";std::string salt,hash;if(!passwordHash(password,salt,hash)){status=500;return "{\"error\":\"password hashing failed\"}";}std::string id="usr_"+std::to_string(GetTickCount64());sqlite3_stmt*q=nullptr;if(sqlite3_prepare_v2(db,"INSERT INTO users(id,username,display_name,role,password_hash,password_salt) VALUES(?,?,?,?,?,?)",-1,&q,nullptr)!=SQLITE_OK){status=500;return "{\"error\":\"account creation failed\"}";}sqlite3_bind_text(q,1,id.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,2,username.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,3,display.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,4,role.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,5,hash.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,6,salt.c_str(),-1,SQLITE_TRANSIENT);int rc=sqlite3_step(q);sqlite3_finalize(q);if(rc!=SQLITE_DONE){status=rc==SQLITE_CONSTRAINT?409:500;return rc==SQLITE_CONSTRAINT?"{\"error\":\"username already exists\"}":"{\"error\":\"account creation failed\"}";}status=201;return "{\"success\":true,\"user\":{\"id\":"+quote(id)+",\"username\":"+quote(username)+",\"displayName\":"+quote(display)+",\"role\":"+quote(role)+"}}";}sqlite3_stmt*q=nullptr;if(sqlite3_prepare_v2(db,"SELECT id,username,display_name,role,password_hash,password_salt FROM users WHERE username=? COLLATE NOCASE",-1,&q,nullptr)!=SQLITE_OK){status=500;return "{\"error\":\"login failed\"}";}sqlite3_bind_text(q,1,username.c_str(),-1,SQLITE_TRANSIENT);if(sqlite3_step(q)!=SQLITE_ROW){sqlite3_finalize(q);status=401;return "{\"error\":\"invalid username or password\"}";}std::string id=col(q,0),name=col(q,1),display=col(q,2),role=col(q,3),saved=col(q,4),salt=col(q,5);sqlite3_finalize(q);if(!constantEqual(saved,deriveWithSalt(password,salt))){status=401;return "{\"error\":\"invalid username or password\"}";}status=200;return "{\"success\":true,\"user\":{\"id\":"+quote(id)+",\"username\":"+quote(name)+",\"displayName\":"+quote(display)+",\"role\":"+quote(role)+"}}";}
static bool initialize(sqlite3* db){std::ifstream f("database/schema.sql");if(!f){std::cerr<<"Cannot read database/schema.sql (run from project root)\n";return false;}std::stringstream b;b<<f.rdbuf();if(!exec(db,b.str()))return false;std::ifstream seed("database/seed.sql");if(seed){std::stringstream data;data<<seed.rdbuf();if(!exec(db,data.str()))return false;}return true;}
static bool saveAnswerSet(sqlite3*db,const std::string&evaluationId,const std::string&type,const std::string&phase,const Json&answers,const Json&questions){if(answers.type!=Json::Array)return true;for(size_t i=0;i<answers.array.size();++i){const Json&answer=answers.array[i];if(answer.type==Json::Null)continue;std::string qid,qtext; if(questions.type==Json::Array&&i<questions.array.size()){qid=text(questions.array[i].get("id"));qtext=text(questions.array[i].get("text"));}if(qtext.empty()&&type=="effectiveness"){sqlite3_stmt*lookup=nullptr;if(sqlite3_prepare_v2(db,"SELECT id,text FROM assessment_questions WHERE assessment_type='effectiveness' AND active=1 ORDER BY sort_order LIMIT 1 OFFSET ?",-1,&lookup,nullptr)==SQLITE_OK){sqlite3_bind_int(lookup,1,(int)i);if(sqlite3_step(lookup)==SQLITE_ROW){qid=col(lookup,0);qtext=col(lookup,1);}sqlite3_finalize(lookup);}}if(qtext.empty())qtext="คำถาม "+std::to_string(i+1);sqlite3_stmt*q=nullptr;const char*sql="INSERT INTO assessment_answers(evaluation_id,question_id,assessment_type,phase,question_text,answer_value) VALUES(?,?,?,?,?,?) ON CONFLICT(evaluation_id,question_id,assessment_type,phase) DO UPDATE SET question_text=excluded.question_text,answer_value=excluded.answer_value";if(sqlite3_prepare_v2(db,sql,-1,&q,nullptr)!=SQLITE_OK)return false;sqlite3_bind_text(q,1,evaluationId.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,2,qid.empty()?nullptr:qid.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,3,type.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,4,phase.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,5,qtext.c_str(),-1,SQLITE_TRANSIENT);std::string value=raw(answer);sqlite3_bind_text(q,6,value.c_str(),-1,SQLITE_TRANSIENT);bool ok=sqlite3_step(q)==SQLITE_DONE;sqlite3_finalize(q);if(!ok)return false;}return true;}
static std::string handle(sqlite3* db,const std::string& method,const std::string& path,const std::string& body,int& status){
 if(method=="GET"&&path=="/health"){status=200;return "{\"status\":\"ok\"}";}
 if(method=="POST"&&(path=="/auth/login"||path=="/auth/register"))return auth(db,path,body,status);
 if(method=="DELETE"&&path=="/evaluations"){if(!exec(db,"BEGIN IMMEDIATE")||!exec(db,"DELETE FROM satisfactions")||!exec(db,"DELETE FROM evaluations")||!exec(db,"COMMIT")){exec(db,"ROLLBACK");status=500;return "{\"error\":\"database clear failed\"}";}status=200;return "{\"success\":true}";}
 if(method=="GET"&&path=="/evaluations"){sqlite3_stmt*q=nullptr;const char*sql="SELECT e.id,e.system_id,e.system_name,e.evaluator_id,e.evaluator_name,e.user_role,e.before_answers,e.after_answers,e.before_average,e.after_average,e.comparable_count,COALESCE(s.answers,'[]'),s.average,e.feedback,e.submitted_at FROM evaluations e LEFT JOIN satisfactions s ON s.evaluation_id=e.id ORDER BY e.submitted_at DESC";if(sqlite3_prepare_v2(db,sql,-1,&q,nullptr)!=SQLITE_OK){status=500;return "{\"error\":\"database query failed\"}";}std::string out="[";bool first=true;while(sqlite3_step(q)==SQLITE_ROW){if(!first)out+=',';first=false;out+=recordJson(q);}sqlite3_finalize(q);status=200;return out+"]";}
 if(method=="POST"&&path=="/evaluations"){Json j=Parser(body).parse();if(j.type!=Json::Object||text(j.get("systemId")).empty()){status=400;return "{\"error\":\"systemId is required\"}";}std::string role=text(j.get("userRole"));if(role!="student"&&role!="teacher"&&role!="staff"){status=400;return "{\"error\":\"userRole must be student, teacher, or staff\"}";}if(!exec(db,"BEGIN IMMEDIATE")){status=500;return "{\"error\":\"database transaction failed\"}";}sqlite3_stmt*q=nullptr;const char*sql="INSERT INTO evaluations(id,system_id,system_name,evaluator_id,evaluator_name,user_role,before_answers,after_answers,before_average,after_average,comparable_count,feedback,submitted_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET system_id=excluded.system_id,system_name=excluded.system_name,evaluator_id=excluded.evaluator_id,evaluator_name=excluded.evaluator_name,user_role=excluded.user_role,before_answers=excluded.before_answers,after_answers=excluded.after_answers,before_average=excluded.before_average,after_average=excluded.after_average,comparable_count=excluded.comparable_count,feedback=excluded.feedback,submitted_at=excluded.submitted_at";if(sqlite3_prepare_v2(db,sql,-1,&q,nullptr)!=SQLITE_OK){exec(db,"ROLLBACK");status=500;return "{\"error\":\"database insert failed\"}";}std::string id=text(j.get("id"));if(id.empty())id="eval_"+std::to_string(GetTickCount64());Json before=j.get("beforeAnswers"),after=j.get("afterAnswers");if(before.type!=Json::Array)before.type=Json::Array;if(after.type!=Json::Array)after.type=Json::Array;sqlite3_bind_text(q,1,id.c_str(),-1,SQLITE_TRANSIENT);bindText(q,2,j.get("systemId"));bindText(q,3,j.get("systemName"));std::string evaluator=text(j.get("evaluatorId"));if(evaluator.empty())evaluator="evaluator_unknown";sqlite3_bind_text(q,4,evaluator.c_str(),-1,SQLITE_TRANSIENT);bindText(q,5,j.get("evaluatorName"));sqlite3_bind_text(q,6,role.c_str(),-1,SQLITE_TRANSIENT);std::string ba=raw(before),aa=raw(after);sqlite3_bind_text(q,7,ba.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,8,aa.c_str(),-1,SQLITE_TRANSIENT);bindNum(q,9,j.get("beforeAverage"));bindNum(q,10,j.get("afterAverage"));sqlite3_bind_int(q,11,(int)j.get("comparableCount").number());bindText(q,12,j.get("feedback"));std::string date=text(j.get("submittedAt"));if(date.empty())date="datetime('now')";sqlite3_bind_text(q,13,date.c_str(),-1,SQLITE_TRANSIENT);bool ok=sqlite3_step(q)==SQLITE_DONE;sqlite3_finalize(q);if(ok){Json sat=j.get("satisfactionAnswers");if(sat.type!=Json::Array)sat.type=Json::Array;std::string answers=raw(sat);sqlite3_stmt*s=nullptr;sqlite3_prepare_v2(db,"INSERT INTO satisfactions(evaluation_id,answers,average) VALUES(?,?,?) ON CONFLICT(evaluation_id) DO UPDATE SET answers=excluded.answers,average=excluded.average",-1,&s,nullptr);sqlite3_bind_text(s,1,id.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,answers.c_str(),-1,SQLITE_TRANSIENT);bindNum(s,3,j.get("satisfactionAverage"));ok=sqlite3_step(s)==SQLITE_DONE;sqlite3_finalize(s);if(ok){sqlite3_stmt*d=nullptr;sqlite3_prepare_v2(db,"DELETE FROM assessment_answers WHERE evaluation_id=?",-1,&d,nullptr);sqlite3_bind_text(d,1,id.c_str(),-1,SQLITE_TRANSIENT);ok=sqlite3_step(d)==SQLITE_DONE;sqlite3_finalize(d);}if(ok){Json questions=j.get("satisfactionQuestions");ok=saveAnswerSet(db,id,"effectiveness","before",before,Json())&&saveAnswerSet(db,id,"effectiveness","after",after,Json())&&saveAnswerSet(db,id,"satisfaction","submitted",sat,questions);}}if(!ok||!exec(db,"COMMIT")){exec(db,"ROLLBACK");status=500;return "{\"error\":\"database write failed\"}";}status=201;return "{\"id\":"+quote(id)+",\"success\":true}";}
 status=404;return "{\"error\":\"not found\"}";
}
static void client(SOCKET sock,sqlite3*db){std::string req;char buf[8192];int n;while((n=recv(sock,buf,sizeof(buf),0))>0){req.append(buf,n);auto p=req.find("\r\n\r\n");if(p!=std::string::npos){size_t len=0;auto h=req.find("Content-Length:");if(h!=std::string::npos)len=std::strtoul(req.c_str()+h+15,nullptr,10);if(req.size()>=p+4+len)break;}}size_t end=req.find("\r\n\r\n");if(end==std::string::npos){closesocket(sock);return;}std::istringstream head(req.substr(0,req.find("\r\n")));std::string method,path,ver;head>>method>>path>>ver;std::string body=req.substr(end+4);int status;std::string out=handle(db,method,path,body,status);std::string label=status==200?"OK":status==201?"Created":status==400?"Bad Request":status==404?"Not Found":"Internal Server Error";std::string resp="HTTP/1.1 "+std::to_string(status)+" "+label+"\r\nContent-Type: application/json; charset=utf-8\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: GET, POST, OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type\r\nConnection: close\r\nContent-Length: "+std::to_string(out.size())+"\r\n\r\n"+out;if(method=="OPTIONS")resp="HTTP/1.1 204 No Content\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: GET, POST, OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type\r\nContent-Length: 0\r\n\r\n";send(sock,resp.c_str(),(int)resp.size(),0);closesocket(sock);}
int main(int argc,char**argv){int port=argc>1?std::atoi(argv[1]):8080;sqlite3*db=nullptr;if(sqlite3_open("database/evaluator.db",&db)!=SQLITE_OK){std::cerr<<"Cannot open database/evaluator.db\n";return 1;}if(!initialize(db))return 1;WSADATA w;if(WSAStartup(MAKEWORD(2,2),&w)){std::cerr<<"Winsock startup failed\n";return 1;}SOCKET server=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);sockaddr_in addr{};addr.sin_family=AF_INET;addr.sin_addr.s_addr=htonl(INADDR_ANY);addr.sin_port=htons((u_short)port);int yes=1;setsockopt(server,SOL_SOCKET,SO_REUSEADDR,(char*)&yes,sizeof yes);if(bind(server,(sockaddr*)&addr,sizeof addr)==SOCKET_ERROR||listen(server,SOMAXCONN)==SOCKET_ERROR){std::cerr<<"Cannot listen on port "<<port<<"\n";return 1;}std::cout<<"Evaluator C++ API listening on http://localhost:"<<port<<"\nDatabase: database/evaluator.db\n";for(;;){SOCKET s=accept(server,nullptr,nullptr);if(s!=INVALID_SOCKET)client(s,db);}sqlite3_close(db);WSACleanup();return 0;}
